window.docContents[136].resolve({"/References/#Type-Systems--References___-Typing-Mutable-References--Properties--Preservation--Weakening-for-Stores":{"contents":"Finally, we need a lemma on store typings, stating that, if a\nstore typing is extended with a new location, the extended one\nstill allows us to assign the same types to the same terms as the\noriginal.\n\ntheorem store_weakening {Γ : Context} {δ δ' : StoreTy} {t : Tm} {τ : Ty}\n  (hExt : Extends δ' δ)\n  (hTy : <{ Γ / δ ⊢ t ⦂ τ }>) :\n  <{ Γ / δ' ⊢ t ⦂ τ }> := by\n    induction hTy with (try (apply_rules using StlcRefTyping; done))\n    | loc_ h =>\n        rw [←extends_lookup] <;> try assumption\n        apply HasType.loc_\n        apply length_extends <;> assumption\n\n\nWe can use the store_weakening lemma to prove that if a store is\nwell typed with respect to a store typing, then the store extended\nwith a new term τ will still be well typed with respect to the\nstore typing extended with τ's type.\n\ntheorem store_well_typed_app {δ : StoreTy} {ρ : Store} {t₁ : Tm} {τ₁ : Ty}\n  (hStoreTy : δ ⊢ ρ)\n  (hTy : <{ ∅ / δ ⊢ t₁ ⦂ τ₁ }>) :\n  (δ.concat τ₁) ⊢ (ρ.concat t₁) := by\n    have ⟨h₁, h₂⟩ := hStoreTy\n    simp_all only [List.concat_eq_append]\n    constructor\n    · simp_all\n    · simp_all only [List.length_append, List.length_cons, List.length_nil, Nat.zero_add]\n      intro l hl\n      inversion hl with\n      | refl =>\n          apply store_weakening <;> try assumption\n          apply extends_app\n          simp_all [MyGetElem.getElem]\n      | step hl =>\n          apply store_weakening <;> try assumption\n          · apply extends_app\n          · have hl' : l < ρ.length := by lia\n            simp_all [MyGetElem.getElem, List.getElem?_append_left]\n\n\n","context":"Type Systems\u0009References: Typing Mutable References\u0009Properties\u0009Preservation","header":"9.5.4.3. Weakening for Stores","id":"/References/#Type-Systems--References___-Typing-Mutable-References--Properties--Preservation--Weakening-for-Stores"},"/Sub/#Type-Systems--Sub___-Subtyping--Formal-Definitions--Subtyping":{"contents":"\n\nsection\nset_option hygiene false in\nlocal notation:40 τ:41 \" <: \" τ':41 => Subtype τ τ'\n\ninductive Subtype : Ty → Ty → Prop where\n  | refl {τ : Ty} :\n      τ <: τ\n  | trans {σ υ τ: Ty}\n      (h₁ : σ <: υ)\n      (h₂ : υ <: τ) :\n      σ <: τ\n  | top {σ : Ty} :\n      σ <: <{ ⊤ }>\n  | arrow { σ₁ σ₂ τ₁ τ₂ : Ty}\n      (h₁ : τ₁ <: σ₁)\n      (h₂ : σ₂ <: τ₂) :\n      <{ σ₁ → σ₂ }> <: <{ τ₁ → τ₂ }>\n\n-- Fill in more rules when you do the `products` exercise\n--  FILL IN HERE\nend\n\nscoped notation:40 τ:41 \" <: \" τ':41 => Subtype τ τ'\n\nattribute [StlcSubTyping] Subtype.refl Subtype.trans Subtype.top\n    Subtype.arrow\n--  FILL IN HERE\n\n\n\n\nNote that we don't need any special rules for base types (Bool\nand Base): they are automatically subtypes of themselves (by\nrefl) and ⊤ (by top), and that's all we want.\n\n\n\n","context":"Type Systems\u0009Sub: Subtyping\u0009Formal Definitions","header":"8.2.2. Subtyping","id":"/Sub/#Type-Systems--Sub___-Subtyping--Formal-Definitions--Subtyping"}});